/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Types: Setup, Reads
 *   Functions: setup, model, entry, trackKey, titleAnswered, guestAnswered, shownFor, proposing, drafted
 * Tests
 *   - lists every change in order; lookup fills of empty values and conflicts answered with lookup arrive selected, while manual changes and lists an unanswered identity owns do not, and choices override all
 *   - a value whose lookup conflict is unanswered is held and cannot be selected, even when chosen
 *   - a pairing-filled number is selected with the tracklist, held without it, and applies alone where the kept tracklist places it
 *   - a deselected pairing-filled number waits for nothing, so selecting it again selects it and its tracklist again
 *   - a saved Track Number at its member's pair position arrives selected where it fills an empty one, so the tracklist it places does too; one replacing a stored number waits for a tick
 *   - an explicit choice holds while its item rests on the same saved values, whatever identity decisions resolve; a newer value needs choosing again
 *   - a tracklist whose paired member an administrator number moves off its row is held and names it, while the other changes stay selected
 *   - Album Artist entries and the label come from the identity read's selection, and members from its member lines, an IDs-only one included
 *   - a member line shows its removed Credits and attribution change, and a deselected member is left out of the body
 *   - preselections and ID writes are narrowed by identity: a shared identity stays while either of its lists is selected, the label only while selected
 *   - lists and a label whose identity needs an answer arrive unselected; ticked, the identity blocks the update and is named; one no selected list owns does not
 *   - identity lines say what applying reuses, creates or records, a created record hidden for a hidden Album
 *   - the Album note names members still crediting a replaced Artist: a deselected member by its current Credits, an unlisted one as the server lists it
 *   - not ready while lookup or analysis waits, before the summary read, when the summary or identity read is of another revision or value revision, or with nothing selected
 *   - a review not captured for lookup lists its field changes only, with empty identity items
 *   - Disc and Track Numbers a title proposal fills into empty values arrive selected, also once saved; Track Numbers alone, replaced values and edited numbers do not
 *   - a cleaned title arrives selected but waits for its member's Disc and Track Number, selected or already stored; an untouched title is never held
 *   - an unsaved draft is counted with the same item bases as once saved, so explicit choices survive the save, and only the saved review is ready
 *   - two members left at one position block the update where a selected number moves one there, a missing Disc Number counting as 1; selected numbers out of bounds block too
 *   - a label whose identity needs an answer arrives unselected, and selected once it is answered
 *   - a 44-track Album on three discs counts 88 proposed numbers and 44 cleaned titles; a member typed onto another's position blocks the update and names both
 *   - a number the administrator saves away from its title leaves every other proposed number and cleaned title as it was before the save
 * @end-catalog */

import { reviewApplyModel, memberKey, type ApplyChoice } from './catalogReviewApplyModel';
import { catalogReview, capturedCatalogReview, slotId, slotTwo } from './catalogReviewFixtures.testSupport';
import { guestCandidateId, guestHandle, leadHandle, leadRecordId, longAlbumReview, pairingReview, reviewAfterLookup, reviewIdentityResponse, reviewLookupResponse, reviewRows }
  from './catalogReviewLookupFixtures.testSupport';
import { titleDefaults, titleProposal, withTitleProposal } from './catalogReviewProposal';
import type { CatalogReview } from './catalogReviewApi';
import type { ReviewIdentityResponse } from './catalogReviewLookupApi';
import type { ReviewLookupView } from './importLookupApi';

/** The format-3 review after its lookup, with the summary's view and identity read of that revision, as the step reads them. */
function setup() {
  const item = reviewAfterLookup(capturedCatalogReview()), { lookup, revision, valueRevision } = reviewLookupResponse(), identity = reviewIdentityResponse();
  return { item, lookup: lookup!, summary: { revision, valueRevision } as { revision: number; valueRevision: number } | null, identity,
    waiting: { lookup: false, analysis: false } as { lookup: boolean; analysis: boolean } | null };
}
type Setup = ReturnType<typeof setup>;
type Reads = { item: CatalogReview; lookup: ReviewLookupView | null; summary?: Setup['summary']; identity: ReviewIdentityResponse | null; waiting: Setup['waiting'] };
/** The model of `reads` with `checked` chosen on each item's current basis, as the step records a click. */
const model = ({ item, lookup, summary = null, identity, waiting }: Reads, checked: Record<string, boolean> = {}) => {
  const bases = reviewApplyModel({ item, lookup, summary, identity, waiting, choices: {} }).items;
  return reviewApplyModel({ item, lookup, summary, identity, waiting, choices: Object.fromEntries(Object.entries(checked).map(([key, value]) =>
    [key, { checked: value, basis: bases.find(entry => entry.key === key)?.basis ?? '' }])) });
};
const entry = (result: ReturnType<typeof model>, key: string) => result.items.find(item => item.key === key)!;
const trackKey = (slot: string, field: string) => `track:${slot}:${field}`;
/** Answers the title conflict with the lookup value, as the server stores the answer. */
function titleAnswered(value: Setup) {
  value.item.draft.album.title = 'Synthetic catalog Album (Complete)';
  value.lookup.applied!.conflicts = value.lookup.applied!.conflicts.map(conflict => conflict.path === 'album.title' ? { ...conflict, answer: 'lookup' } : conflict);
  value.lookup.needsAnswer.conflicts = value.lookup.needsAnswer.conflicts.filter(path => path !== 'album.title');
  return value;
}
/** The guest saved as created: no identity row needs an answer, so the lists it shares arrive selected. */
function guestAnswered(value: Setup) {
  value.identity.identities[0].needsAnswer = false;
  return value;
}
/** What a confirmation of `lists` and `label` shows, as the server narrows its items by identity. */
const shownFor = (identity: ReviewIdentityResponse, lists: string[], label: boolean) => {
  const owned = new Set(identity.identities.filter(row => row.entries.some(item => lists.includes(item.path))).map(row => row.id));
  const shown = (item: { scope: string; identity: string | null }) => item.scope === 'label' ? label : owned.has(item.identity!);
  return { preselections: identity.preselections.filter(shown), musicBrainzIds: identity.musicBrainzIds.filter(shown) };
};

test('lists every change in order; lookup fills of empty values and conflicts answered with lookup arrive selected, while manual changes and lists an unanswered identity owns do not, and choices override all', () => {
  const value = titleAnswered(setup());
  value.item.draft.tracks[0].title = 'Manual track correction';
  const result = model(value);
  expect(result.items.map(item => item.key)).toEqual(['album::title', 'album::releaseDate', 'album::artists', 'album::expectedTracklist', trackKey(slotId, 'title'),
    trackKey(slotTwo, 'trackNumber'), memberKey(slotTwo)]);
  // The title conflict answered with the lookup value replaces the stored title as the administrator chose; the guest both lists
  // share still needs an answer.
  expect(result.items.map(item => [item.key, item.selected])).toEqual([['album::title', true], ['album::releaseDate', false], ['album::artists', false], ['album::expectedTracklist', true],
    [trackKey(slotId, 'title'), false], [trackKey(slotTwo, 'trackNumber'), true], [memberKey(slotTwo), false]]);
  expect(entry(result, 'album::title').value).toEqual({ kind: 'value', baseline: 'Synthetic catalog Album', value: 'Synthetic catalog Album (Complete)' });
  const chosen = model(value, { 'album::title': false, [trackKey(slotId, 'title')]: true, [trackKey(slotTwo, 'trackNumber')]: false });
  expect([entry(chosen, 'album::title').selected, entry(chosen, trackKey(slotId, 'title')).selected, entry(chosen, trackKey(slotTwo, 'trackNumber')).selected]).toEqual([false, true, false]);
  expect(chosen.selection.fields).not.toContainEqual({ scope: 'album', slotId: null, field: 'title' });
  expect(chosen.selection.fields).toContainEqual({ scope: 'track', slotId, field: 'title' });
  expect(chosen.selection.fields).not.toContainEqual({ scope: 'track', slotId: slotTwo, field: 'trackNumber' });
  // A value lookup filled over a stored one, which nobody chose, arrives unselected; the title answered with the lookup value stays selected.
  value.lookup.applied!.values = [...value.lookup.applied!.values, { path: `tracks.${slotId}.title`, slotId }];
  expect([entry(model(value), trackKey(slotId, 'title')).selected, entry(model(value), 'album::title').selected]).toEqual([false, true]);
  // Once the guest is answered, the lists it owns arrive selected.
  const answered = model(guestAnswered(value));
  expect([entry(answered, 'album::artists').selected, entry(answered, memberKey(slotTwo)).selected]).toEqual([true, true]);
});

test('a value whose lookup conflict is unanswered is held and cannot be selected, even when chosen', () => {
  const result = model(setup(), { 'album::releaseDate': true, 'album::title': true });
  expect([entry(result, 'album::releaseDate').hold, entry(result, 'album::releaseDate').selected]).toEqual(['conflict', false]);
  expect(result.selection.fields).not.toContainEqual({ scope: 'album', slotId: null, field: 'releaseDate' });
  // The first member's Artists are an open conflict too: the identity read lists no line for it, so it is not an item at all.
  expect(result.items.some(item => item.key === memberKey(slotId))).toBe(false);
});

test('a pairing-filled number is selected with the tracklist, held without it, and applies alone where the kept tracklist places it', () => {
  const value = setup(), number = trackKey(slotTwo, 'trackNumber');
  const withTracklist = model(value);
  expect([entry(withTracklist, number).selected, entry(withTracklist, number).hold]).toEqual([true, null]);
  expect(entry(withTracklist, 'album::expectedTracklist').value).toEqual({ kind: 'tracklist', keptRows: null, keptNoFile: 0, rows: 3, noFile: 1 });
  expect(withTracklist.selection.fields).toEqual(expect.arrayContaining([{ scope: 'album', slotId: null, field: 'expectedTracklist' }, { scope: 'track', slotId: slotTwo, field: 'trackNumber' }]));
  const without = model(value, { 'album::expectedTracklist': false });
  expect([entry(without, number).selected, entry(without, number).hold]).toEqual([false, 'tracklist']);
  // The Album keeps a tracklist with a row at the pair's position: the number applies alone, and the tracklist shows the rows kept.
  value.identity.keptTracklist = [reviewRows()[0], reviewRows()[2]];
  const kept = model(value, { 'album::expectedTracklist': false });
  expect([entry(kept, number).selected, entry(kept, number).hold]).toEqual([true, null]);
  expect(entry(kept, 'album::expectedTracklist').value).toEqual({ kind: 'tracklist', keptRows: 2, keptNoFile: 1, rows: 3, noFile: 1 });
  // A kept tracklist without that position places nothing.
  value.identity.keptTracklist = [reviewRows()[0]];
  expect(entry(model(value, { 'album::expectedTracklist': false }), number).hold).toBe('tracklist');
});

test('a deselected pairing-filled number waits for nothing, so selecting it again selects it and its tracklist again', () => {
  const value = setup(), number = trackKey(slotTwo, 'trackNumber');
  const unticked = model(value, { [number]: false });
  // Its member leaves its row, which holds the tracklist, but the number itself stays selectable.
  expect([entry(unticked, number).selected, entry(unticked, number).hold]).toEqual([false, null]);
  expect(entry(unticked, 'album::expectedTracklist')).toMatchObject({ selected: false, hold: 'placement', offSlotIds: [slotTwo] });
  expect(unticked.selection.fields).not.toContainEqual({ scope: 'track', slotId: slotTwo, field: 'trackNumber' });
  const ticked = model(value, { [number]: true });
  expect([entry(ticked, number).selected, entry(ticked, number).hold]).toEqual([true, null]);
  expect(entry(ticked, 'album::expectedTracklist')).toMatchObject({ selected: true, hold: null, offSlotIds: [] });
});

test('a saved Track Number at its member\'s pair position arrives selected where it fills an empty one, so the tracklist it places does too; one replacing a stored number waits for a tick', () => {
  const value = setup();
  // The Album stored no Track Number and the administrator saved Track 1, on which lookup re-ranked the pairing (the first member at 1:1).
  value.item.source.tracks[0].trackNumber = null;
  const result = model(value);
  expect(entry(result, trackKey(slotId, 'trackNumber'))).toMatchObject({ selected: true, hold: null, value: { kind: 'value', baseline: null, value: 1 } });
  expect(entry(result, 'album::expectedTracklist')).toMatchObject({ selected: true, hold: null, offSlotIds: [] });
  expect(entry(result, trackKey(slotTwo, 'trackNumber'))).toMatchObject({ selected: true, hold: null });
  // It can be deselected like any other change; a saved number at no pair position stays unselected.
  expect(entry(model(value, { [trackKey(slotId, 'trackNumber')]: false }), 'album::expectedTracklist')).toMatchObject({ hold: 'placement', offSlotIds: [slotId] });
  // The Album stored Track 7: the saved 1 replaces it, so it arrives unselected and the tracklist it places waits for it, with the
  // number that applies with that tracklist; ticking it selects all three.
  value.item.source.tracks[0].trackNumber = 7;
  const replacing = model(value);
  expect(entry(replacing, trackKey(slotId, 'trackNumber'))).toMatchObject({ selected: false, hold: null, value: { kind: 'value', baseline: 7, value: 1 } });
  expect(entry(replacing, 'album::expectedTracklist')).toMatchObject({ selected: false, hold: 'placement', offSlotIds: [slotId] });
  expect(entry(replacing, trackKey(slotTwo, 'trackNumber'))).toMatchObject({ selected: false, hold: 'tracklist' });
  const ticked = model(value, { [trackKey(slotId, 'trackNumber')]: true });
  expect([trackKey(slotId, 'trackNumber'), 'album::expectedTracklist', trackKey(slotTwo, 'trackNumber')].map(key => entry(ticked, key).selected)).toEqual([true, true, true]);
  value.item.draft.tracks[0].trackNumber = 2;
  expect(entry(model(value), trackKey(slotId, 'trackNumber')).selected).toBe(false);
});

test('an explicit choice holds while its item rests on the same saved values, whatever identity decisions resolve; a newer value needs choosing again', () => {
  const value = guestAnswered(titleAnswered(setup())), keys = ['album::title', 'album::artists', 'album::expectedTracklist', memberKey(slotTwo)];
  const bases = model(value).items, choices: Record<string, ApplyChoice> = Object.fromEntries(keys.map(key => [key, { checked: false, basis: bases.find(item => item.key === key)!.basis }]));
  const selected = () => { const result = reviewApplyModel({ ...value, choices }); return keys.map(key => entry(result, key).selected); };
  expect(selected()).toEqual([false, false, false, false]);
  // A saved identity decision binds the guest: the new Credits name its record, while the review's values stay the same.
  value.identity.members[0] = { ...value.identity.members[0], next: value.identity.members[0].next.map(credit => ({ ...credit, subjectId: guestCandidateId })) };
  value.identity.album = { ...value.identity.album!, next: value.identity.album!.next.map(credit => credit.identity === guestHandle ? { ...credit, subjectId: guestCandidateId } : credit) };
  expect(selected()).toEqual([false, false, false, false]);
  // A newer saved title, Album entries, tracklist and member entries are other values: each arrives with its default again, the
  // title unselected as it replaces the stored one and is no longer the lookup value the conflict was answered with.
  value.item.draft.album.title = 'Synthetic catalog Album (Deluxe)';
  value.item.draft.album.artists = value.item.draft.album.artists.slice(0, 1);
  value.item.draft.album.expectedTracklist = [...reviewRows(), { ...reviewRows()[2], trackNumber: 4 }];
  value.item.draft.tracks[1].artists = [{ ...value.item.draft.tracks[1].artists![0], name: 'Synthetic guest (newer)' }];
  expect(selected()).toEqual([false, true, true, true]);
});

test('a tracklist whose paired member an administrator number moves off its row is held and names it, while the other changes stay selected', () => {
  const value = guestAnswered(setup());
  value.item.draft.tracks[0].trackNumber = 2;
  const unselected = model(value);
  expect(entry(unselected, 'album::expectedTracklist').selected).toBe(true);
  const result = model(value, { [trackKey(slotId, 'trackNumber')]: true });
  expect(entry(result, 'album::expectedTracklist')).toMatchObject({ selected: false, hold: 'placement', offSlotIds: [slotId] });
  expect([entry(result, trackKey(slotId, 'trackNumber')).selected, entry(result, 'album::artists').selected, entry(result, memberKey(slotTwo)).selected]).toEqual([true, true, true]);
  // Its pairing-filled number now waits for the tracklist.
  expect(entry(result, trackKey(slotTwo, 'trackNumber')).hold).toBe('tracklist');
  // Deselecting the filled number moves its member off its row too.
  expect(entry(model(value, { [trackKey(slotTwo, 'trackNumber')]: false }), 'album::expectedTracklist')).toMatchObject({ hold: 'placement', offSlotIds: [slotTwo] });
});

test('Album Artist entries and the label come from the identity read\'s selection, and members from its member lines, an IDs-only one included', () => {
  const value = guestAnswered(setup()), label = { creditId: 'synthetic_label_credit', subjectType: 'organization' as const, subjectId: '141414141414141414141414', identity: null, name: 'Synthetic Label',
    role: 'label' as const, joinPhrase: null };
  value.identity.selection = { lists: [`tracks.${slotTwo}.artists`], label: true };
  value.identity.album = { ...value.identity.album!, current: [...value.identity.album!.current, label], next: [...value.identity.album!.next, { ...label, creditId: null, subjectId: null, name: 'Looked Up Label' }] };
  value.identity.members[0] = { ...value.identity.members[0], next: value.identity.members[0].current, credits: false, attribution: null };
  const result = model(value);
  expect(result.items.some(item => item.key === 'album::artists')).toBe(false);
  expect(entry(result, 'album::label').value).toEqual({ kind: 'credits', current: [label], next: [{ ...label, creditId: null, subjectId: null, name: 'Looked Up Label' }], idsOnly: false });
  expect(entry(result, memberKey(slotTwo))).toMatchObject({ member: true, field: 'artists', title: 'Synthetic second track', selected: true,
    value: { kind: 'member', current: [], next: [], removed: [], attribution: null, idsOnly: true } });
  expect(result.selection.memberCredits).toEqual([slotTwo]);
  expect(result.selection.fields).toContainEqual({ scope: 'album', slotId: null, field: 'label' });
  // The Album's entries change only in IDs when the read shows the same Credits.
  value.identity.selection = { lists: ['album.artists'], label: false };
  value.identity.album = { ...value.identity.album, next: value.identity.album.current };
  expect(entry(model(value), 'album::artists').value).toMatchObject({ kind: 'credits', idsOnly: true });
});

test('a member line shows its removed Credits and attribution change, and a deselected member is left out of the body', () => {
  const value = setup(), removed = { creditId: 'synthetic_old_credit', subjectType: 'artist' as const, subjectId: leadRecordId, identity: null, name: 'Synthetic old Artist', role: 'primary' as const, joinPhrase: null };
  value.identity.members[0] = { ...value.identity.members[0], current: [removed], removedCreditIds: [removed.creditId] };
  const result = model(value);
  expect(entry(result, memberKey(slotTwo)).value).toMatchObject({ removed: [removed], attribution: { from: 'unknown', to: 'documented' }, idsOnly: false });
  expect(model(value, { [memberKey(slotTwo)]: false }).selection.memberCredits).toEqual([]);
});

test('preselections and ID writes are narrowed by identity: a shared identity stays while either of its lists is selected, the label only while selected', () => {
  const value = guestAnswered(setup());
  value.identity.selection.label = true;
  value.identity.label = { name: 'Looked Up Label', musicBrainzId: null, state: 'unbound', bound: null, decision: null, needsAnswer: false, musicBrainzIdWrite: null,
    preselection: { scope: 'label', identity: null, boundName: 'Looked Up Label', action: 'create-distinct', candidateId: null, candidateRevision: null } };
  value.identity.album!.next.push({ creditId: null, subjectType: 'organization', subjectId: null, identity: null, name: 'Looked Up Label', role: 'label', joinPhrase: null });
  value.identity.preselections = [{ scope: 'artist', identity: guestHandle, boundName: 'Synthetic guest', action: 'create-distinct', candidateId: null, candidateRevision: null }, value.identity.label.preselection!];
  value.identity.musicBrainzIds = [{ scope: 'artist', identity: leadHandle, musicBrainzId: '00000000-0000-4000-8000-0000000000a1', replaces: null }];
  const cases: [Record<string, boolean>, string[], boolean][] = [[{}, ['album.artists', `tracks.${slotTwo}.artists`], true],
    [{ 'album::artists': false }, [`tracks.${slotTwo}.artists`], true], [{ [memberKey(slotTwo)]: false, 'album::label': false }, ['album.artists'], false],
    [{ 'album::artists': false, [memberKey(slotTwo)]: false }, [], true]];
  for (const [choices, lists, label] of cases) {
    const { selection } = model(value, choices);
    expect({ preselections: selection.preselections, musicBrainzIds: selection.musicBrainzIds }, JSON.stringify(choices)).toEqual(shownFor(value.identity, lists, label));
  }
  expect(model(value, { 'album::artists': false }).selection.preselections.map(item => item.identity)).toEqual([guestHandle, null]);
  expect(model(value, { 'album::artists': false, [memberKey(slotTwo)]: false }).selection.preselections.map(item => item.identity)).toEqual([null]);
});

test('lists and a label whose identity needs an answer arrive unselected; ticked, the identity blocks the update and is named; one no selected list owns does not', () => {
  const value = setup(), unticked = model(value);
  expect([entry(unticked, 'album::artists').selected, entry(unticked, memberKey(slotTwo)).selected, unticked.blocking.identities, unticked.ready]).toEqual([false, false, [], true]);
  const result = model(value, { 'album::artists': true });
  expect([result.blocking.identities, result.ready]).toEqual([['Synthetic guest'], false]);
  const line = result.selection.identities.find(item => item.handle === guestHandle)!;
  expect([line.outcome, line.needsAnswer, line.records]).toEqual(['undecided', true, []]);
  const lead = result.selection.identities.find(item => item.handle === leadHandle)!;
  expect([lead.outcome, lead.records]).toEqual(['reuse', [{ name: 'Synthetic catalog Artist', hidden: true }]]);
  const deselected = model(value, { 'album::artists': false, [memberKey(slotTwo)]: false });
  expect([deselected.blocking.identities, deselected.selection.identities, deselected.ready]).toEqual([[], [], true]);
});

test('identity lines say what applying reuses, creates or records, a created record hidden for a hidden Album', () => {
  const value = setup();
  value.item.source.album.visibility = value.item.draft.album.visibility = 'hidden';
  const guest = value.identity.identities[0];
  value.identity.identities[0] = { ...guest, needsAnswer: false, decision: { scope: 'artist', identity: guestHandle, boundName: guest.name, boundMusicBrainzId: null, action: 'create-distinct', candidateId: null,
    candidateRevision: null } };
  value.identity.identities[1] = { ...value.identity.identities[1], musicBrainzIdWrite: { scope: 'artist', identity: leadHandle, musicBrainzId: '00000000-0000-4000-8000-0000000000a1',
    replaces: '00000000-0000-4000-8000-0000000000a2' } };
  let lines = model(value).selection.identities;
  expect(lines.map(line => [line.handle, line.outcome, line.records, line.idWrite])).toEqual([
    [guestHandle, 'create', [{ name: 'Synthetic guest', hidden: true }], null],
    [leadHandle, 'reuse', [{ name: 'Synthetic catalog Artist', hidden: true }], { musicBrainzId: '00000000-0000-4000-8000-0000000000a1', replaces: '00000000-0000-4000-8000-0000000000a2', record: 'Synthetic catalog Artist' }]]);
  // A decided reuse names its candidate; one listed at another revision since needs an answer again.
  const candidate = value.identity.candidates.items[0];
  value.identity.identities[0] = { ...value.identity.identities[0], decision: { ...value.identity.identities[0].decision!, action: 'reuse', candidateId: guestCandidateId, candidateRevision: candidate.revision } };
  lines = model(value).selection.identities;
  expect([lines[0].outcome, lines[0].records]).toEqual(['reuse', [{ name: 'Synthetic guest', hidden: false }]]);
  value.identity.candidates.items[0] = { ...candidate, revision: 'd'.repeat(64) };
  expect(model(value).selection.identities[0].outcome).toBe('undecided');
});

test('the Album note names members still crediting a replaced Artist: a deselected member by its current Credits, an unlisted one as the server lists it', () => {
  const value = guestAnswered(setup()), lead = value.identity.album!.current[0];
  value.item.draft.tracks.push({ slotId: '10000000-0000-4000-8000-000000000003', title: 'Synthetic third track', discNumber: null, trackNumber: 3, artists: [] });
  const third = value.item.draft.tracks[2].slotId;
  value.identity.album = { ...value.identity.album!, next: [{ ...lead, creditId: null, subjectId: null, identity: guestHandle, name: 'Synthetic guest' }], replacedPrimaryArtistIds: [leadRecordId],
    membersNamingReplaced: [third] };
  value.identity.members[0] = { ...value.identity.members[0], current: [{ ...lead, creditId: 'synthetic_member_lead' }] };
  expect(model(value).selection.albumNote).toEqual({ namingReplaced: [third] });
  expect(model(value, { [memberKey(slotTwo)]: false }).selection.albumNote).toEqual({ namingReplaced: [slotTwo, third] });
  // No note when the Album's entries are deselected, or when its primary Artists stay the same.
  expect(model(value, { 'album::artists': false }).selection.albumNote).toBeNull();
  expect(model(setup()).selection.albumNote).toBeNull();
});

test('not ready while lookup or analysis waits, before the summary read, when the summary or identity read is of another revision or value revision, or with nothing selected', () => {
  const value = setup();
  value.identity.identities[0].needsAnswer = false;
  expect(model(value).ready).toBe(true);
  expect(model({ ...value, waiting: { lookup: true, analysis: false } })).toMatchObject({ ready: false, blocking: { lookup: true } });
  expect(model({ ...value, waiting: { lookup: false, analysis: true } }).ready).toBe(false);
  expect(model({ ...value, waiting: null }).ready).toBe(false);
  expect(model({ ...value, identity: { ...value.identity, revision: 2 } }).ready).toBe(false);
  expect(model({ ...value, identity: { ...value.identity, valueRevision: 2 } }).ready).toBe(false);
  // A cached summary read of an older value revision supplied the pairing and conflicts: the selection waits for this one.
  expect(model({ ...value, summary: { revision: 1, valueRevision: 0 } }).ready).toBe(false);
  expect(model({ ...value, summary: { revision: 2, valueRevision: 1 } }).ready).toBe(false);
  expect(model({ ...value, summary: null }).ready).toBe(false);
  // Without the identity read a captured review lists no review-only item and cannot apply.
  const missing = model({ ...value, identity: null });
  expect([missing.items.map(item => item.key), missing.ready]).toEqual([['album::releaseDate', trackKey(slotTwo, 'trackNumber')], false]);
  const none = Object.fromEntries(model(value).items.map(item => [item.key, false]));
  expect(model(value, none)).toMatchObject({ ready: false, selection: { fields: [], memberCredits: [] } });
});

test('a review not captured for lookup lists its field changes only, with empty identity items', () => {
  const item = catalogReview(); item.suggestions = []; item.draft.album.title = 'Manual Album correction';
  const result = reviewApplyModel({ item, lookup: null, summary: null, waiting: null, identity: null, choices: {} });
  expect(result.items.map(value => [value.key, value.selected, value.hold])).toEqual([['album::title', false, null]]);
  expect(result.ready).toBe(false);
  const chosen = model({ item, lookup: null, waiting: null, identity: null }, { 'album::title': true });
  expect(chosen.ready).toBe(true);
  expect(chosen.selection).toEqual({ fields: [{ scope: 'album', slotId: null, field: 'title' }], memberCredits: [], preselections: [], musicBrainzIds: [], items: [chosen.items[0]],
    identities: [], albumNote: null });
});

/** A review's title proposal as the page derives it: the saved draft with the proposal written in (titles cleaned with `cleanup`) and its defaults. */
const proposing = (item: CatalogReview, cleanup = false) => {
  const proposal = titleProposal(item.source.tracks, item.draft.tracks);
  return { draft: withTitleProposal(item.draft, proposal, cleanup), proposed: titleDefaults(item.source.tracks, item.draft.tracks) };
};
/** The model of an unsaved `draft` of a review without reads (a captured one lists field items only), with `checked` chosen on each item's basis. */
const drafted = (item: CatalogReview, extra: Pick<Parameters<typeof reviewApplyModel>[0], 'draft' | 'proposed'>, checked: Record<string, boolean> = {}) => {
  const base = { item, lookup: null, summary: null, waiting: null, identity: null, ...extra };
  const bases = reviewApplyModel({ ...base, choices: {} }).items;
  return reviewApplyModel({ ...base, choices: Object.fromEntries(Object.entries(checked).map(([key, value]) => [key, { checked: value, basis: bases.find(entry => entry.key === key)?.basis ?? '' }])) });
};

test('Disc and Track Numbers a title proposal fills into empty values arrive selected, also once saved; Track Numbers alone, replaced values and edited numbers do not', () => {
  const item = pairingReview(), { draft, proposed } = proposing(item), numbers = [slotId, slotTwo].flatMap(slot => [trackKey(slot, 'discNumber'), trackKey(slot, 'trackNumber')]);
  const unsaved = drafted(item, { draft, proposed });
  expect(numbers.map(key => [key, entry(unsaved, key).selected])).toEqual(numbers.map(key => [key, true]));
  // Saved, the captured titles still give the same numbers: the same items, bases and defaults.
  const saved = { ...item, draft }, after = drafted(saved, { proposed: proposing(saved).proposed });
  expect(after.items.map(value => [value.key, value.basis, value.selected])).toEqual(unsaved.items.map(value => [value.key, value.basis, value.selected]));
  // Without the proposal's defaults the same numbers are the administrator's own and arrive unselected.
  expect(numbers.map(key => entry(drafted(item, { draft }), key).selected)).toEqual([false, false, false, false]);
  // A number edited away from its title's position is the administrator's own.
  const edited = { ...draft, tracks: draft.tracks.map(track => track.slotId === slotTwo ? { ...track, trackNumber: 5 } : track) };
  expect(entry(drafted(item, { draft: edited, proposed }), trackKey(slotTwo, 'trackNumber')).selected).toBe(false);
  // Titles giving Track Numbers alone propose them unselected.
  const trackOnly = { ...item, source: { ...item.source, tracks: item.source.tracks.map((track, index) => ({ ...track, title: `0${index + 1} - Synthetic` })) } };
  expect(drafted(trackOnly, proposing(trackOnly)).items.filter(value => value.selected)).toEqual([]);
  // Saved over a stored number, the title's number replaces it: unselected until ticked.
  const replacing = { ...saved, source: { ...saved.source, tracks: saved.source.tracks.map(track => track.slotId === slotId ? { ...track, trackNumber: 7 } : track) } };
  expect(entry(drafted(replacing, { proposed: proposing(replacing).proposed }), trackKey(slotId, 'trackNumber'))).toMatchObject({ selected: false, value: { baseline: 7, value: 1 } });
});

test('a cleaned title arrives selected but waits for its member\'s Disc and Track Number, selected or already stored; an untouched title is never held', () => {
  const item = pairingReview(), { draft, proposed } = proposing(item, true), title = trackKey(slotId, 'title');
  const all = drafted(item, { draft, proposed });
  expect(entry(all, title)).toMatchObject({ selected: true, hold: null, value: { kind: 'value', baseline: '1-01 Synthetic opening (Live)', value: 'Synthetic opening (Live)' } });
  for (const field of ['discNumber', 'trackNumber']) {
    const without = drafted(item, { draft, proposed }, { [trackKey(slotId, field)]: false });
    expect([entry(without, title).hold, entry(without, title).selected, entry(without, trackKey(slotTwo, 'title')).selected], field).toEqual(['numbers', false, true]);
  }
  // Unticked, the title waits for nothing; ticked again with its numbers deselected, it waits again.
  expect(entry(drafted(item, { draft, proposed }, { [title]: false, [trackKey(slotId, 'trackNumber')]: false }), title)).toMatchObject({ hold: null, selected: false });
  // Where the Album already stores both numbers, the cleaned title applies alone.
  const stored = { ...item, source: { ...item.source, tracks: item.source.tracks.map(track => ({ ...track, discNumber: 1, trackNumber: track.slotId === slotId ? 1 : 2 })) } };
  const storedDraft = { ...draft, tracks: draft.tracks.map(track => ({ ...track, discNumber: 1, trackNumber: track.slotId === slotId ? 1 : 2 })) };
  expect(entry(drafted(stored, { draft: storedDraft, proposed }), title)).toMatchObject({ hold: null, selected: true });
  // A title the administrator wrote otherwise is an ordinary edit: unselected and never held.
  const typed = { ...draft, tracks: draft.tracks.map(track => track.slotId === slotId ? { ...track, title: 'Synthetic opening' } : track) };
  expect(entry(drafted(item, { draft: typed, proposed }, { [trackKey(slotId, 'trackNumber')]: false }), title)).toMatchObject({ hold: null, selected: false });
});

test('an unsaved draft is counted with the same item bases as once saved, so explicit choices survive the save, and only the saved review is ready', () => {
  const item = catalogReview(); item.suggestions = [];
  const draft = { ...item.draft, album: { ...item.draft.album, title: 'Edited synthetic Album' }, tracks: item.draft.tracks.map(track => track.slotId === slotTwo ? { ...track, trackNumber: 2 } : track) };
  const unsaved = drafted(item, { draft }, { 'album::title': true, [trackKey(slotTwo, 'trackNumber')]: true });
  expect([unsaved.selection.fields.length, unsaved.ready]).toEqual([2, false]);
  const choices = Object.fromEntries(unsaved.items.map(value => [value.key, { checked: true, basis: value.basis }]));
  const saved = reviewApplyModel({ item: { ...item, draft }, lookup: null, summary: null, waiting: null, identity: null, choices });
  expect([saved.items.map(value => [value.key, value.basis, value.selected]), saved.ready]).toEqual([unsaved.items.map(value => [value.key, value.basis, value.selected]), true]);
  // Readiness is read without a draft: one passed is never ready, even when equal to the saved one.
  expect(reviewApplyModel({ item: { ...item, draft }, draft: structuredClone(draft), lookup: null, summary: null, waiting: null, identity: null, choices }).ready).toBe(false);
});

test('two members left at one position block the update where a selected number moves one there, a missing Disc Number counting as 1; selected numbers out of bounds block too', () => {
  const item = catalogReview(); item.suggestions = [];
  // The second member typed into the first member's Track 1, on no Disc and on Disc 1: both share position 1:1 once selected.
  for (const disc of [null, 1]) {
    const draft = { ...item.draft, tracks: item.draft.tracks.map(track => track.slotId === slotTwo ? { ...track, discNumber: disc, trackNumber: 1 } : track) };
    expect(drafted(item, { draft }).blocking.positions, String(disc)).toEqual([]);
    const chosen = drafted({ ...item, draft }, {}, { [trackKey(slotTwo, 'trackNumber')]: true });
    expect([chosen.blocking.positions, chosen.ready], String(disc)).toEqual([[{ reason: 'duplicate', slotIds: [slotId, slotTwo] }], false]);
  }
  const other = { ...item.draft, tracks: item.draft.tracks.map(track => track.slotId === slotTwo ? { ...track, discNumber: 2, trackNumber: 1 } : track) };
  // On Disc 2 it is apart only with its Disc Number selected too; without it the member stays on no disc, which is Disc 1.
  expect(drafted({ ...item, draft: other }, {}, { [trackKey(slotTwo, 'trackNumber')]: true }).blocking.positions).toEqual([{ reason: 'duplicate', slotIds: [slotId, slotTwo] }]);
  expect(drafted({ ...item, draft: other }, {}, { [trackKey(slotTwo, 'trackNumber')]: true, [trackKey(slotTwo, 'discNumber')]: true }).blocking.positions).toEqual([]);
  // Two members the catalog already stores at one position block nothing an update does not move.
  const shared = { ...item, source: { ...item.source, tracks: item.source.tracks.map(track => ({ ...track, trackNumber: 1 })) },
    draft: { ...item.draft, album: { ...item.draft.album, title: 'Edited synthetic Album' }, tracks: item.draft.tracks.map(track => ({ ...track, trackNumber: 1 })) } };
  expect(drafted(shared, {}, { 'album::title': true })).toMatchObject({ ready: true, blocking: { positions: [] } });
  // A selected number out of the server's bounds blocks; unselected, it is not applied.
  const both = { [trackKey(slotTwo, 'discNumber')]: true, [trackKey(slotTwo, 'trackNumber')]: true };
  for (const [disc, track] of [[1000, 2], [1, 10_000], [0, 2], [1, 0], [1, 1.5]]) {
    const draft = { ...item.draft, tracks: item.draft.tracks.map(value => value.slotId === slotTwo ? { ...value, discNumber: disc, trackNumber: track } : value) };
    expect(drafted(item, { draft }).blocking.positions, `${disc}-${track}`).toEqual([]);
    expect(drafted(item, { draft }, both).blocking.positions, `${disc}-${track}`).toEqual([{ reason: 'range', slotIds: [slotTwo] }]);
  }
  const bounds = { ...item.draft, tracks: item.draft.tracks.map(value => value.slotId === slotTwo ? { ...value, discNumber: 999, trackNumber: 9999 } : value) };
  expect(drafted(item, { draft: bounds }, both).blocking.positions).toEqual([]);
});

