test('a 44-track Album on three discs counts 88 proposed numbers and 44 cleaned titles; a member typed onto another\'s position blocks the update and names both', () => {
  const item = longAlbumReview(), { draft, proposed } = proposing(item, true);
  const result = drafted(item, { draft, proposed });
  expect([result.items.length, result.selection.fields.length, result.blocking.positions]).toEqual([132, 132, []]);
  // The 20th member (Disc 2, Track 5) typed as Track 4 sits on the 19th member's position.
  const slot = (index: number) => item.source.tracks[index].slotId;
  const typo = { ...draft, tracks: draft.tracks.map((track, index) => index === 19 ? { ...track, trackNumber: 4 } : track) };
  const blocked = drafted(item, { draft: typo, proposed }, { [trackKey(slot(19), 'trackNumber')]: true });
  expect(blocked.blocking.positions).toEqual([{ reason: 'duplicate', slotIds: [slot(18), slot(19)] }]);
  // Deselecting a disc's numbers holds its cleaned titles, which wait for them.
  const discOne = item.source.tracks.slice(0, 15).flatMap(track => [trackKey(track.slotId, 'discNumber'), trackKey(track.slotId, 'trackNumber')]);
  const partial = drafted(item, { draft, proposed }, Object.fromEntries(discOne.map(key => [key, false])));
  expect(partial.items.filter(value => value.hold === 'numbers').map(value => value.slotId)).toEqual(item.source.tracks.slice(0, 15).map(track => track.slotId));
  expect(partial.selection.fields).toHaveLength(132 - 45);
});

test('a number the administrator saves away from its title leaves every other proposed number and cleaned title as it was before the save', () => {
  const item = longAlbumReview(), { draft, proposed } = proposing(item, true), slot = (index: number) => item.source.tracks[index].slotId;
  // The 20th member's Track Number corrected by hand to 9: it no longer matches its title, so it is the administrator's own.
  const edited = { ...draft, tracks: draft.tracks.map((track, index) => index === 19 ? { ...track, trackNumber: 9 } : track) };
  const unsaved = drafted(item, { draft: edited, proposed }), saved = { ...item, draft: edited };
  const after = drafted(saved, { proposed: proposing(saved).proposed });
  expect(after.items.map(value => [value.key, value.basis, value.selected, value.hold])).toEqual(unsaved.items.map(value => [value.key, value.basis, value.selected, value.hold]));
  expect([after.selection.fields.length, entry(after, trackKey(slot(19), 'trackNumber')).selected, entry(after, trackKey(slot(19), 'title')).hold]).toEqual([130, false, 'numbers']);
  expect(after.items.filter(value => value.slotId !== slot(19)).every(value => value.selected)).toBe(true);
  expect(after.blocking.positions).toEqual([]);
});
